from app.db import execute, TransientConnectionError
from app.writer import record_batch

settings = {'db': {'primary': 'dsn', 'reconnect_attempts': 3, 'backoff_ms': 0}}

# succeeds on 3rd attempt
calls = {'n': 0}
class Conn:
    def run(self, op):
        calls['n'] += 1
        if calls['n'] < 3:
            raise TransientConnectionError()
        return 'row-1'

def connect(dsn):
    return Conn()

print('result:', execute({'id': 1}, connect, settings))
print('calls:', calls['n'])

# always fails -> propagates after budget used
class AlwaysFail:
    def run(self, op):
        raise TransientConnectionError()

def connect_fail(dsn):
    return AlwaysFail()

try:
    execute({'id': 2}, connect_fail, settings)
except TransientConnectionError:
    print('propagated as expected')

# record_batch marks as failed
def connect_fail2(dsn):
    return AlwaysFail()
print(record_batch([{'id': 3}], connect_fail2, settings))

# other exception not retried
class OtherErr:
    def run(self, op):
        raise ValueError('boom')

n = {'c':0}
def connect_other(dsn):
    n['c']+=1
    return OtherErr()
try:
    execute({'id':4}, connect_other, settings)
except ValueError:
    print('ValueError propagated, connect called', n['c'], 'times')
"

